MAXIMUM_CHAPTERS = 18
CHAPTER_TIMEOUT = 1800
LOOP_BUDGET_LIMIT = 86340


def run(request, story, outline, chapter_workflow_id):
    limit = min(max(int(request.get("max_chapters", MAXIMUM_CHAPTERS)), 1), MAXIMUM_CHAPTERS)
    chapters = outline[:limit]
    chapter_timeout = request.get("chapter_timeout_seconds", CHAPTER_TIMEOUT)
    budget = min(max(len(chapters), 1) * chapter_timeout, LOOP_BUDGET_LIMIT)
    config = {}

    for key in ("revision_workflow_id", "max_revisions"):
        if key in request:
            config[key] = request[key]

    return {
        "settings": {
            "workflow_id": request.get("chapter_workflow_id", chapter_workflow_id),
            "max_iterations": len(chapters),
            "child_timeout_seconds": chapter_timeout,
            "budget_seconds": request.get("chapter_budget_seconds", budget),
            "state": {
                "config": config,
                "story": story,
                "outline": chapters,
                "notes": "No chapters have been written yet.",
                "chapter_count": 0,
            },
        },
        "outline": chapters,
    }
